end
local Dn=math.max(1,bb.wave())
local En=Cn.n/Dn
local Fn
if#Cn.hpK>0 then
local Gn=table.clone(Cn.hpK)
table.sort(Gn)
Fn=Gn[math.floor(#Gn/2)+1]
end
local Hn=type(P.hunt.starfall)==Avd[1659]and P.hunt.starfall or{}
local In=(tonumber(Hn.runs)or 0)+1
local Jn=1/math.min(In,5)
P.hunt.starfall={runs=In,perWave=Hn.perWave and(Hn.perWave+(En-Hn.perWave)*Jn)or En,hpK=Fn and(Hn.hpK and(Hn.hpK+(Fn-Hn.hpK)*Jn)or Fn)or Hn.hpK,at=os.time()}
local Kn,Ln
for Mn in pairs(Cn.waves)do
Kn=math.min(Kn or Mn,Mn)
Ln=math.max(Ln or Mn,Mn)
end
F.log(1,Avd[1874],string.format(Avd[1875],Cn.n,Dn,En,tostring(Kn),tostring(Ln),Fn or 0))
return{n=Cn.n,waves=Dn,hpK=Fn and math.floor(Fn*100+0.5)/100 or nil}
end
