F.saveSoon()
F.log(1,Avd[1918],string.format(Avd[1919],kb.charmWords(aq),tostring(_p.label),math.floor((tonumber(_p.p)or 0)*100+0.5),(tonumber(_p.p)or 0)>=0.92 and Avd[1910]or Avd[1821]))
else
