function kb.weatherStrength(dq)
local eq=kb.fx(dq)
local fq=eq.dmg/eq.cd/eq.hp/eq.speed*(1+(eq.range-1)/2)
for gq,hq in pairs(eq.kinds)do
fq=fq*(1+bb.rogueShare(gq)*hq)
end
if eq.ice>0 then
local iq=bb.rogueShare(Avd[1793])
fq=fq*(iq+(1-iq)/(1-eq.ice+eq.ice/fb.modFactor(Avd[1921])))
end
if eq.fly>0 then
fq=fq*(1-eq.fly*0.5)
end
if eq.noCC then
fq=fq*0.95
end
if eq.shroud then
fq=fq*0.9
end
if eq.zap then
fq=fq*0.85
end
return fq/kb.weatherK(dq)
end
kb.WEATHER_K_MIN,kb.WEATHER_K_MAX,kb.WEATHER_K_RUNS=0.5,4,10
function kb.weatherK(jq)
local kq=jq and type(P.hunt)==Avd[1659]and type(P.hunt.wk)==Avd[1659]and P.hunt.wk[tostring(jq)]or nil
return type(kq)==Avd[1659]and tonumber(kq.k)or 1
end
function kb.weatherLearn()
if bb.withOthers or#game:GetService(Avd[563]):GetPlayers()>1 then
return
end
local lq=bb.huntWeather or kb.weatherNow()
local mq,nq=bb.pred,bb.calRun
if not lq or type(mq)~=Avd[1659]or type(nq)~=Avd[1659]then
return
end
local function oq(pq,qq)
return type(pq)==Avd[1659]and tonumber(pq[qq]or pq[tostring(qq)])or nil
end
local rq={}
for sq=2,bb.wave()do
local tq,uq=oq(nq.alive,sq),oq(mq.aliveAt,sq)
if tq and uq and tq>0 and uq>0 then
table.insert(rq,tq/uq)
end
end
if#rq<3 then
return
end
table.sort(rq)
local vq=rq[math.ceil(#rq/2)]
P.hunt.wk=type(P.hunt.wk)==Avd[1659]and P.hunt.wk or{}
local wq=P.hunt.wk[tostring(lq)]
local xq=math.min(kb.WEATHER_K_RUNS-1,type(wq)==Avd[1659]and tonumber(wq.n)or 0)
local yq=kb.weatherK(lq)
local zq=math.max(1,xq)
local Aq=math.exp((zq*math.log(yq)+math.log(yq*vq))/(zq+1))
Aq=U.clamp(Aq,kb.WEATHER_K_MIN,kb.WEATHER_K_MAX)
bb.wkWas={w=tostring(lq),old=wq}
P.hunt.wk[tostring(lq)]={k=Aq,n=(type(wq)==Avd[1659]and tonumber(wq.n)or 0)+1,at=os.time()}
F.log(1,Avd[1922],string.format(Avd[1923],tostring(lq),vq,tostring(lq),Aq,yq,P.hunt.wk[tostring(lq)].n))
end
