local Lq=kb.board()
if Kq and Lq and Bq.weather~=Avd[1879]and not Lq.weathers[Bq.weather]then
Dq=Dq+(1000+5000*O.pearlValue+50*W.remnantGems(Avd[1877]))/kb.WEATHERS
end
