function kb.skinPlan()
local hr,ir=N.session(),N.prof()
local jr=N.data(Avd[1823])or{}
local kr=(ir.inventory and ir.inventory.unique_items)or ir.unique_items or{}
local lr,mr={},{kinds={},sell={},wear={},pearls=0,missing={}}
for nr,pr in pairs(kr)do
