if qr and qr.item_group==Avd[1823]and qr._skin_set==kb.SKIN_SET and qr.usage and jr[qr.usage.skin_id]then
local rr=lr[pr.item_id]
if not rr then
rr={id=pr.item_id,name=qr.name,rarity=qr.rarity,skinId=qr.usage.skin_id,skin=jr[qr.usage.skin_id],uuids={}}
