function gb.pullGoal()
local vI=O.pullGoal
if type(vI)~=Avd[570]or vI==Avd[584]or type(N.Units[vI])~=Avd[1659]then
return nil
end
local wI=N.prof()
if not wI then
return nil
end
local xI=N.Units[vI]
local yI=xI.evolve and xI.evolve.evolve_unit or vI
local zI={id=vI,to=yI,coins=N.cur(Avd[2280]),itemCost=0,needCoins=0}
for AI,BI in pairs(xI.evolve and xI.evolve.normal and xI.evolve.normal.item_requirement or{})do
local CI=N.SaleEvent[BI.item_id]
if CI and type(CI.resource_cost)==Avd[1659]and CI.resource_cost.id==Avd[2280]then
zI.item,zI.itemCost=BI.item_id,tonumber(CI.resource_cost.amount)or 0
end
end
zI.haveItem=zI.item~=nil and gb.have(zI.item)>0
local DI,EI=ab.hatched[vI]or false,false
for FI,GI in pairs(wI.collection.owned_units)do
if GI.unit_id==vI then
DI=true
end
if GI.unit_id==yI then
EI=true
end
end
if EI then
zI.step=Avd[2281]
elseif not DI then
zI.step,zI.needCoins=Avd[2282],1
elseif zI.item and not zI.haveItem then
zI.step,zI.needCoins=Avd[2251],math.max(0,zI.itemCost-zI.coins)
else
zI.step=Avd[1753]
end
return zI
end
