local DK=CK.quest_info
local EK=DK and DK.quest_class
if EK and EK.class==Avd[2319]and type(EK.unit_ids)==Avd[1659]then
local FK=tonumber(EK.amount)or 0
local GK=FK-(tonumber(CK.quest_progress and CK.quest_progress.amount)or 0)
if GK>0 then
local HK=W.levelSpawns(xK,EK.unit_ids)
if HK>0 then
local IK=tonumber(DK.quest_reward and DK.quest_reward.gem_reward)or 0
for JK,KK in pairs(DK.quest_reward and DK.quest_reward.item or{})do
if type(KK)==Avd[1659]and KK.item_id then
IK=IK+W.itemValue(KK.item_id,tonumber(KK.max_amount or KK.amount or KK.min_amount)or 1)
end
end
zK=zK+IK*math.min(1,HK/GK)
AK=string.format(Avd[2320],tostring(DK.quest_name),U.fmt(FK-GK),U.fmt(FK),U.fmt(math.min(HK,GK)))
end
end
end
end
return zK,AK
