function W.portalMod(sL)
local tL,uL={weak={},strong={},res={}},false
for vL,wL in pairs(type(sL.weak)==Avd[1659]and sL.weak or{})do
local xL=type(wL)==Avd[1659]and wL.damage_type or(type(wL)==Avd[570]and wL)or nil
if xL and xL~=Avd[584]then
uL=true
tL.weak[xL]=W.weakAmp(type(wL)==Avd[1659]and wL.amplification)
end
