for yL,zL in pairs(type(sL.strong)==Avd[1659]and sL.strong or{})do
local AL=type(zL)==Avd[1659]and zL.damage_type or(type(zL)==Avd[570]and zL)or nil
local BL=type(zL)==Avd[1659]and tonumber(zL.amplification)
if AL and AL~=Avd[584]then
uL=true
if BL and BL<1 then
tL.res[AL]=BL
else
tL.strong[AL]=true
end
end
end
return uL and tL or nil
end
function W.weakAmp(CL)
CL=tonumber(CL)
if not CL then
