end
iM=iM+W.itemValue(mM,nM)
table.insert(jM,string.format(Avd[2322],U.fmt(nM),(N.Items[mM]or{}).name or mM,oM and Avd[584]or Avd[2323]))
end
local pM,qM=pcall(db.hiveDrops,gM)
for rM,sM in pairs(pM and type(qM)==Avd[1659]and qM or{})do
if not table.find(WL,rM)then
iM=iM+W.itemValue(rM,tonumber(sM)or 0)
