if P.str.relicTeam==nil or P.str.relicTeam==W.teamSig()then
return jb.RELIC_SETTLED_GAIN
end
return jb.RELIC_MOVE_GAIN
end
function jb.relicWorth(OQ,PQ)
local QQ=PQ._unique_item_data and PQ._unique_item_data._unique_relic_data
if not QQ then
return 0
end
local RQ=N.Items[PQ.item_id]or{}
local SQ,TQ=V.types(OQ.unit_id)
if RQ.main_damage_type and RQ.main_damage_type~=Avd[2373]and RQ.main_damage_type~=TQ then
return 0
end
local UQ,VQ=0,0
for WQ,XQ in pairs(QQ._core_damage_type_buffs or{})do
if SQ[XQ.damage_type]then
UQ=UQ+(tonumber(XQ.mul)or 0)+(tonumber(XQ.add_upg)or 0)*0.01+(tonumber(XQ.pen)or 0)*0.001
VQ=VQ+(tonumber(XQ.crit)or 0)
end
end
UQ=UQ+VQ*0.5
local YQ=V.rows(OQ.unit_id)
local ZQ=YQ and YQ[YQ.max]
local _Q=(ZQ and tonumber(ZQ.cd)or 0)*V.mult(OQ,Avd[1822])
for aR,bR in pairs(QQ._unique_relic_effects or{})do
local cR=type(bR.params)==Avd[1659]and bR.params or{}
if bR.id==Avd[2374]then
local dR=math.min(1,(tonumber(cR.extra_damage)or 0)*_Q/math.max(1,tonumber(cR.time_interval)or 40))
local eR=V.DRONES and V.DRONES[OQ.unit_id]
if eR and eR.late and _Q>0 then
local fR=1/_Q
dR=dR*fR/(fR+(tonumber(eR.max)or 0)*(tonumber(eR.late.dmg)or 0)*(tonumber(eR.hits)or 1)/math.max(0.1,tonumber(eR.late.cd)or 4))
end
UQ=UQ+dR
elseif bR.id==Avd[2375]then
UQ=UQ+(tonumber(cR.dmg_buff)or 0)*0.25
elseif bR.id==Avd[2376]then
UQ=UQ+(tonumber(cR.dmg_buff)or 0)*VQ
elseif bR.id==Avd[2377]then
if SQ.magic then
UQ=0
else
UQ=UQ+(tonumber(cR.dmg_buff)or 0)*0.3
end
elseif bR.id==Avd[2378]then
if SQ.water_damage then
UQ=UQ+0.05
end
end
end
return UQ
end
function jb.relicPlan()
local gR=N.session()
if not gR then
return nil
end
local hR=gR.inventory and gR.inventory.inventory_profile_data or{}
local iR={}
for jR,kR in ipairs(hR.unique_items or{})do
if type(kR)==Avd[1659]and kR.uuid and(N.Items[kR.item_id]or{}).item_group==Avd[2379]then
table.insert(iR,kR)
end
end
local lR={}
for mR,nR in ipairs(V.equipped())do
local oR=nR.data and nR.data.rarity
if not V.isFarm(nR.id)and(oR==Avd[1951]or oR==Avd[1952]or oR==Avd[2358]or oR==Avd[2380])then
local pR=jb.share(nR.id)
if not P.str.share[nR.id]then
pR=math.min(pR,0.15)
end
local qR={}
for rR,sR in ipairs(iR)do
local tR=jb.relicWorth(nR.u,sR)*pR*100
if tR>0.01 then
table.insert(qR,{it=sR,w=tR})
end
end
table.sort(qR,function(uR,vR)
if uR.w~=vR.w then
return uR.w>vR.w
end
return uR.it.uuid<vR.it.uuid
end)
local wR,xR={},{}
for yR,zR in ipairs(qR)do
local AR=xR[zR.it.item_id]or 0
if#wR<6 and AR<((N.Items[zR.it.item_id]or{}).unique_equip and 1 or 2)then
xR[zR.it.item_id]=AR+1
table.insert(wR,zR)
end
end
if nR.u._equipped_relic then
local BR=false
for CR,DR in ipairs(wR)do
if DR.it.uuid==nR.u._equipped_relic then
BR=true
end
end
local ER=not BR and gR.inventory:get_item_by_uuid(nR.u._equipped_relic)
if ER then
table.insert(wR,{it=ER,w=jb.relicWorth(nR.u,ER)*pR*100})
end
end
table.insert(lR,{e=nR,share=pR,opts=wR})
end
end
local FR,GR={},-1
local HR,IR,JR={},{},{}
local function KR(LR,MR)
if LR> #lR then
if MR>GR then
GR=MR
FR=table.clone(HR)
end
return
end
local NR=lR[LR]
HR[NR.e.uuid]=nil
KR(LR+1,MR)
for OR,PR in ipairs(NR.opts)do
local QR=(N.Items[PR.it.item_id]or{}).unique_equip
if not IR[PR.it.uuid]and not(QR and JR[PR.it.item_id])then
IR[PR.it.uuid]=true
if QR then
JR[PR.it.item_id]=true
end
HR[NR.e.uuid]=PR.it.uuid
KR(LR+1,MR+PR.w+(PR.it.uuid==NR.e.u._equipped_relic and 0.01 or 0))
HR[NR.e.uuid]=nil
IR[PR.it.uuid]=nil
if QR then
JR[PR.it.item_id]=nil
end
end
end
end
KR(1,0)
local RR,SR=0,{}
for TR,UR in ipairs(lR)do
local VR=UR.e.u._equipped_relic and gR.inventory:get_item_by_uuid(UR.e.u._equipped_relic)
local WR=VR and jb.relicWorth(UR.e.u,VR)*UR.share*100 or 0
RR=RR+WR
local XR=FR[UR.e.uuid]and gR.inventory:get_item_by_uuid(FR[UR.e.uuid])
local YR=XR and jb.relicWorth(UR.e.u,XR)*UR.share*100 or 0
table.insert(SR,string.format(Avd[2381],V.name(UR.e.id),VR and(N.Items[VR.item_id]or{}).name or Avd[1962],WR,XR and(N.Items[XR.item_id]or{}).name or Avd[1962],YR))
end
return FR,GR-RR,SR,lR
end
function jb.relicsApply(ZR)
if not(O.team and O.teamRelics)or O.strDry then
return false
end
local _R=W.teamSig()
