if not oS then
return true
end
local qS=U.now()
F.request(Avd[2383],Avd[2384],nS)
while U.now()-qS<4 and pS._equipped_relic==nS do
task.wait(0.25)
end
task.wait(1.2)
if pS._equipped_relic==nS then
F.log(1,Avd[2364],string.format(Avd[2385],V.name(pS.unit_id),tostring(V.relicName(pS)),kS(qS)))
F.backoff(Avd[2383],300)
