end
return true
end
F.log(1,Avd[2364],string.format(Avd[2386],bS,table.concat(cS,Avd[1888])))
for rS,sS in ipairs(dS)do
local tS=sS.e.u._equipped_relic
if tS and tS~=aS[sS.e.uuid]and not mS(tS)then
