end
local LS=U.now()
F.request(Avd[2383],Avd[1917],CS,{unit_uuid=BS.e.uuid})
while U.now()-LS<4 and BS.e.u._equipped_relic~=CS do
task.wait(0.25)
end
task.wait(1.2)
if BS.e.u._equipped_relic~=CS then
F.log(1,Avd[2364],string.format(Avd[2387],(N.Items[(eS.inventory:get_item_by_uuid(CS)or{}).item_id]or{}).name or Avd[2388],V.name(BS.e.id),kS(LS)))
F.backoff(Avd[2383],300)
P.str.relicAt=0
return false
end
zS=zS+1
end
end
W._sigAt=nil
P.str.relicSig=W.teamSig()
P.str.relicTeam=P.str.relicSig
P.str.relicNote=string.format(Avd[2389],bS)
jb.note(string.format(Avd[2390],zS,bS))
