local ET=(not zT and Avd[2396])or(iT<1 and Avd[2397])or(CT<hT and string.format(Avd[2398],math.floor(CT),math.floor(hT)))or nil
local FT=(not zT and Avd[2399])or(iT<1 and Avd[2400])or(CT<hT and Avd[2401])or nil
