function jb.xpRate()
local RT=N.session()
if not RT then
return 0
end
local TT=0
for UT,VT in ipairs(jb.core())do
local WT=RT.collection:get_unit_by_uuid(VT)
if WT then
local XT,YT=jb.gainXp(WT,500000)
if YT>0 then
TT=math.max(TT,XT/YT)
end
end
end
local ZT=TT*(O.strengthValue or 300)
if(tonumber(N.cur(Avd[1723]))or 0)>(O.xpGoldFloor or 100000)then
ZT=math.min(ZT,(N.GOLD_VALUE or 0.02)/14)
end
return ZT
end
function jb.xpGuess(_T)
local aU=_T.level and N.Levels[_T.level]
if not aU then
return 0
end
local bU=math.min(9,tonumber(aU.story_world_rank)or tonumber(_T.rank)or 9)
local cU=tonumber(aU.story_level_rank)or 6
local dU=(_T.kind==Avd[1697]and 1.5 or 1)*(bU>5 and 2 or 1)
local eU=2.1564^(bU-1)*(40+10*cU)/dU
if _T.kind==Avd[1678]then
eU=3*30*2.1564^(bU-1)/dU
end
local fU=bU>=9 and 0.3 or(bU>=7 and 0.5 or 1)
return eU*fU*6
end
function jb.modeBonus(gU)
if not(O.team and O.teamXp)or gU.kind==Avd[1679]or gU.kind==Avd[1676]then
return 0
end
local hU=jb._xpRate and os.time()-(jb._xpRateAt or 0)<300 and jb._xpRate or nil
if not hU then
hU=jb.xpRate()
jb._xpRate,jb._xpRateAt=hU,os.time()
end
if hU<=0 then
return 0
end
local iU=P.modes and P.modes[gU.key]
local jU=tonumber(iU and iU.xp)or jb.xpGuess(gU)
local kU=jU*hU
if kU<1 then
return 0
end
return kU,string.format(Avd[2404],U.fmt(jU),math.floor(kU+0.5))
end
function jb.xpSettle()
local lU=P.lastRun
if not(lU and type(lU.xp0)==Avd[1659]and lU.key)then
return
end
local mU=N.session()
if not mU then
