end
local nU,oU=0,0
for pU,qU in pairs(lU.xp0)do
local rU=mU.collection:get_unit_by_uuid(pU)
if rU then
nU=nU+math.max(0,(tonumber(rU.xp)or 0)-(tonumber(qU)or 0))
oU=oU+1
end
end
P.lastRun=nil
if oU==0 then
return
end
local sU=W.rec(lU.key)
sU.xp=sU.xp and(sU.xp+(nU-sU.xp)*0.3)or nU
if nU>0 then
F.log(2,jb.LOG,string.format(Avd[2405],lU.key,U.fmt(nU)))
end
F.saveSoon()
end
