function jb.feedPlan(uU)
local vU=V.trait(uU)
local wU=vU==Avd[2406]and 1.5 or 1
local xU=math.max(0,jb.xpFor(uU.unit_id,jb.cap(uU))-(tonumber(uU.xp)or 0))
local yU,zU,AU={},0,0
for BU,CU in ipairs(jb.foodHeld())do
local DU=CU.xp*wU
local EU=math.min(CU.n,math.floor((xU-zU)/math.max(1,DU)))
if EU>0 then
yU[CU.id]=EU
zU=zU+EU*DU
AU=AU+EU
end
end
return{feed=yU,planned=zU,n=AU}
end
function jb.run(FU)
