end
local SU=GU.collection:get_unit_by_uuid(FU.uuid)or HU
local TU=(tonumber(SU.xp)or 0)-NU
if TU>0 then
local UU=jb.level(SU)
local VU=UU>OU and string.format(Avd[2394],OU,UU)or string.format(Avd[2395],OU)
cb.add(string.format(Avd[2409],MU,FU.name),MU,Avd[2410],string.format(Avd[2411],U.fmt(TU),VU))
jb.note(string.format(Avd[2412],FU.name,MU,U.fmt(TU),VU,math.abs(TU-KU)>KU*0.1 and string.format(Avd[2413],U.fmt(KU))or Avd[584]))
else
jb.note(string.format(Avd[2414],FU.name,tostring(PU and QU or Avd[1975])))
F.backoff(Avd[2392],600)
end
elseif FU.kind==Avd[2402]then
ab.fuseInto(FU.uuid,false)
end
