F.log(1,Avd[2873],string.format(Avd[2874],_cb.label,xdb:sub(1,400)))
local ydb=xdb:find(Avd[2875])or xdb:find(Avd[1673])or xdb:find(Avd[2876])or xdb:find(Avd[2877])or xdb:find(Avd[2878])
