end
else
local Vdb=Odb-(tonumber(Mdb.held)or 0)
Pdb(Avd[2317]..Mdb.portal,math.max(0,Vdb))
F.log(1,Avd[2873],string.format(Avd[2889],W.levelName(W.PORTALS[Mdb.portal].from),Vdb,Udb,Odb,Ndb>0 and string.format(Avd[2890],Ndb,Tdb)or Avd[584]))
