function ab.relicClash(Ydb)
local Zdb=N.session()
local _db={}
for aeb,beb in ipairs(P.savedTeam or{})do
_db[beb]=true
end
local ceb={}
for deb,eeb in ipairs(Ydb)do
local feb=Zdb.collection:get_unit_by_uuid(eeb)
local geb=feb and feb._equipped_relic and Zdb.inventory:get_item_by_uuid(feb._equipped_relic)
if geb and geb.item_id and(N.Items[geb.item_id]or{}).unique_equip then
table.insert(ceb,{uuid=eeb,u=feb,kind=geb.item_id,relic=feb._equipped_relic,k=(_db[eeb]and 1e12 or 0)+jb.score(feb)})
end
end
table.sort(ceb,function(heb,ieb)
if heb.k~=ieb.k then
return heb.k>ieb.k
end
return heb.uuid<ieb.uuid
end)
local jeb={}
for keb,leb in ipairs(ceb)do
if jeb[leb.kind]then
local meb=(N.Items[leb.kind]or{}).name or leb.kind
local neb,oeb=F.request(Avd[2891],Avd[2384],leb.relic)
local peb=U.now()
while U.now()-peb<3 and leb.u._equipped_relic==leb.relic do
task.wait(0.25)
end
if leb.u._equipped_relic~=leb.relic then
P.relicOff[leb.uuid]=leb.relic
F.log(1,Avd[2417],string.format(Avd[2892],V.name(leb.u.unit_id),meb,V.name(jeb[leb.kind])))
else
F.log(1,Avd[2417],string.format(Avd[2893],V.name(leb.u.unit_id),meb,tostring(oeb)))
end
else
jeb[leb.kind]=leb.u.unit_id
end
end
end
function ab.relicBack()
