for xeb,yeb in ipairs(V.equipped())do
local zeb=yeb.u._equipped_relic and qeb.inventory:get_item_by_uuid(yeb.u._equipped_relic)
if zeb and zeb.item_id==ueb.item_id then
web=yeb
