end
if web then
P.str.reequip={uuid=web.uuid,slot=web.slot}
F.saveNow()
F.request(Avd[1977],Avd[1978],web.uuid)
local Aeb=U.now()
while U.now()-Aeb<4 and jb.slotOf(web.uuid)do
task.wait(0.25)
end
end
F.request(Avd[2891],Avd[1917],seb,{unit_uuid=reb})
local Beb=U.now()
while U.now()-Beb<3 and teb._equipped_relic~=seb do
task.wait(0.25)
end
if web then
jb.reequip()
end
F.log(1,Avd[2417],string.format(Avd[2894],V.name(teb.unit_id),(N.Items[ueb.item_id]or{}).name or tostring(ueb.item_id),teb._equipped_relic==seb and Avd[584]or Avd[2895]))
