table.insert(gfb,V.name(ifb.id))
end
F.log(1,Avd[2417],Avd[2902]..tostring(Deb)..Avd[2903]..table.concat(gfb,Avd[1769])..Avd[2904]..table.concat(Qeb,Avd[1888]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local jfb,kfb={},{}
for lfb,mfb in ipairs(V.equipped())do
kfb[mfb.uuid]=true
end
for nfb,ofb in ipairs(P.savedTeam or{})do
if not kfb[ofb]and N.session().collection:get_unit_by_uuid(ofb)then
table.insert(jfb,ofb)
end
end
local pfb=0
for qfb,rfb in ipairs(jfb)do
