return F.saveSoon()
end
Bfb[Cfb]=Hfb
local Lfb=P.savedTeam
P.savedTeam=nil
if ab.equipTeam(Bfb,string.format(Avd[2910],V.name(yfb.into),V.name(yfb.out)))then
P.savedTeam,P.ownSwap=nil,nil
W.lastScored=nil
if F.notify then
F.notify(Avd[2911],string.format(Avd[2912],V.name(yfb.into),V.name(yfb.out)),Avd[2300])
end
else
P.savedTeam=Lfb or P.savedTeam
end
F.saveSoon()
