task.wait()
local lvb=(gvb+hvb)/2
local mvb=bvb(math.exp(lvb))
if not mvb then
return nil
end
if mvb>=0 then
hvb=lvb
else
gvb=lvb
end
end
return math.exp(hvb)
end
