local mxb={}
for nxb,oxb in ipairs(fxb)do
table.insert(mxb,oxb.t)
end
local pxb,qxb=pcall(bb.label)
F.log(1,Avd[3077],string.format(Avd[3078],tostring(pxb and qxb or bb.key),table.concat(mxb,Avd[1888])))
end
function fb.dmgLearn(rxb)
