local Ixb,Jxb=pcall(bb.label)
F.log(1,Avd[3077],string.format(Avd[3079],tostring(Ixb and Jxb or bb.key),sxb.won and(Axb and Avd[3080]or Avd[3081])or(Avd[3082]..tostring(sxb.wave)),(not Axb and rxb)and Avd[2120]or(Avd[3083]..yxb),Fxb,table.concat(Gxb,Avd[1769]),Hxb and Avd[3084]or Avd[584]))
