xKb,yKb,lKb=CKb,EKb,DKb
end
end
end
end
if xKb then
YJb=xKb
end
end
local function FKb(GKb,HKb)
local IKb=fb.teamFrom(GKb,TJb.map)
return(fb.objective(HKb)+fb.objective(fb.run(TJb,IKb,{hpMul=ZJb*0.92}))+fb.objective(fb.run(TJb,IKb,{hpMul=ZJb*1.08})))/3
end
local JKb,KKb=lKb or _Jb,FKb(YJb,lKb or _Jb)
if type(VJb.rest)==Avd[1659]and#VJb.rest>0 then
local LKb,MKb
for NKb,OKb in ipairs(YJb)do
if not V.isFarm(OKb.unit_id)and not V.allyBuff(OKb.unit_id)then
local PKb,QKb=pcall(V.score,OKb,TJb.mod)
QKb=(PKb and QKb or 0)*V.skinMul(OKb,TJb.skinSet)
if not MKb or QKb<MKb then
LKb,MKb=NKb,QKb
end
end
end
if LKb then
local RKb,SKb={},U.now()
for TKb,UKb in ipairs(VJb.rest)do
if U.now()-SKb>5 then
break
end
local VKb=false
for WKb,XKb in ipairs(YJb)do
if XKb.unit_id==UKb.unit_id then
VKb=true
end
end
if not VKb then
local YKb=table.clone(YJb)
YKb[LKb]=UKb
table.insert(RKb,{u=UKb,o=fb.objective(fb.run(TJb,fb.teamFrom(YKb,TJb.map),{hpMul=ZJb}))})
end
end
table.sort(RKb,function(ZKb,_Kb)
return ZKb.o>_Kb.o
end)
VJb=table.clone(VJb)
for aLb=1,math.min(4,#RKb)do
table.insert(VJb,1,RKb[aLb].u)
end
XJb=XJb+(U.now()-SKb)
end
end
for bLb=1,2 do
local cLb=false
for dLb=1,#YJb do
for eLb,fLb in ipairs(VJb)do
if U.now()-XJb>WJb then
return YJb,JKb,ZJb,_Jb
end
local gLb=false
for hLb,iLb in ipairs(YJb)do
if iLb.unit_id==fLb.unit_id then
gLb=true
end
end
if not gLb then
local jLb=table.clone(YJb)
jLb[dLb]=fLb
if(not fKb or aKb(jLb)>0)and gKb(jLb)>=math.min(8,gKb(YJb))then
local kLb=fb.run(TJb,fb.teamFrom(jLb,TJb.map),{hpMul=ZJb})
local lLb=fb.objective(kLb)
if lLb>KKb+1 then
lLb=FKb(jLb,kLb)
if lLb>KKb+1 then
YJb,KKb,JKb,cLb=jLb,lLb,kLb,true
end
end
end
end
end
end
if not cLb then
break
end
end
return YJb,JKb,ZJb,_Jb
end
function fb.evolutions()
