P.dg.sim[JRb]=nil
end
F.saveSoon()
return not CRb.none and CRb or nil
end
function ib.winP(NRb)
local ORb=tostring(math.min(4,math.max(1,math.ceil(NRb.d/5))))
local PRb=P.dg.depth[ORb]or{runs=0,wins=0}
local QRb=U.clamp(0.95-0.015*NRb.d,0.5,0.95)
local RRb=((tonumber(PRb.wins)or 0)+QRb*2)/((tonumber(PRb.runs)or 0)+2)
local SRb,TRb=pcall(ib.sim,NRb)
if SRb and TRb and TRb.p then
local URb,VRb=pcall(fb.styleP,TRb,TRb.zone==false and Avd[3112]or(TRb.zone and Avd[3092]or nil))
RRb=(RRb*2+(URb and VRb or TRb.p))/3
end
return RRb,SRb and TRb or nil
end
function ib.hopeless(WRb)
return WRb~=nil and WRb.won==false and(tonumber(WRb.p)or 1)<=0.05
end
function ib.stake(XRb)
local YRb,ZRb,_Rb=ib.res(XRb)
return ZRb+2*_Rb
end
function ib.curseBar(aSb,bSb)
local cSb=ib.stake(aSb)
if bSb>=15 or cSb>=8 then
return 0.9,Avd[3260],cSb
end
if bSb>=10 or cSb>=4 then
return 0.6,Avd[3261],cSb
end
return 0.1,Avd[3262],cSb
end
function ib.blindCurse(dSb,eSb)
return ib.fxText(ib.fx(dSb,eSb))==ib.fxText(ib.fx(dSb))
end
function ib.curseOk(fSb,gSb,hSb,iSb,jSb)
local kSb=tostring((ib.item(fSb)or{}).name or fSb)
local lSb,mSb,nSb=ib.curseBar(gSb,hSb)
if lSb>0.2 and ib.blindCurse(gSb,fSb)then
return false,string.format(Avd[3263],kSb,nSb)
end
local function oSb(pSb)
return pSb==nil or(tonumber(pSb.p)or 1)>=lSb
end
if iSb then
local qSb,rSb=pcall(ib.sim,iSb,nil,true)
if qSb and not oSb(rSb)then
return false,string.format(Avd[3264],kSb,(mSb:gsub(Avd[3265],Avd[3266])),tostring(rSb.margin or Avd[1931]))
end
end
if#jSb==0 then
return true
end
local sSb
for tSb,uSb in ipairs(jSb)do
local vSb,wSb=pcall(ib.sim,uSb,fSb,true)
if not vSb or oSb(wSb)then
return true
end
if not sSb or(tonumber(wSb.p)or 0)>(tonumber(sSb.p)or 0)then
sSb=wSb
end
end
return false,string.format(Avd[3267],kSb,mSb,tostring(sSb and sSb.margin or Avd[1931]))
end
function ib.curseGate(xSb,ySb)
