end
function ib.payValue()
local ASb,BSb=0,0
for CSb,DSb in ipairs(P.dg.pay or{})do
if type(DSb.items)==Avd[1659]then
local ESb=tonumber(DSb.gems)or 0
for FSb,GSb in pairs(DSb.items)do
if(tonumber(GSb)or 0)>0 then
ESb=ESb+W.itemValue(FSb,GSb)
end
end
ASb,BSb=ASb+ESb,BSb+1
end
end
if BSb<5 then
return nil
end
return ASb/BSb*0.7
end
function ib.pick(HSb)
local ISb,JSb=ib.curses(HSb),ib.lives(HSb)
local KSb=ib.res(HSb)
local LSb=ib.rooms(HSb)
local MSb={}
for NSb,OSb in ipairs(LSb)do
table.insert(MSb,tostring(OSb.r._r))
end
local PSb=table.concat(MSb,Avd[2368])..string.format(Avd[3268],JSb,KSb,ISb,W.teamSig())
if ib._pick and ib._pick.sig==PSb then
return ib._pick.x
end
local QSb,RSb
for SSb,TSb in ipairs(LSb)do
local USb=ib.roomValue(TSb,KSb)
local VSb,WSb
for XSb,YSb in ipairs(ib.after(HSb,TSb.choice))do
local ZSb=ib.roomValue(YSb,KSb)
if not VSb or ZSb>VSb then
VSb,WSb=ZSb,YSb
end
end
local _Sb,aTb=ib.winP(TSb)
local bTb=1-(1-_Sb)^math.max(1,JSb)
local cTb=JSb>=3 and 1 or(JSb==2 and 2 or 6)
TSb.p,TSb.sim,TSb.value,TSb.nextValue,TSb.nextRoom=_Sb,aTb,USb,VSb or 0,WSb
TSb.score=bTb*(USb+0.6*(VSb or 0))-(1-_Sb)*cTb
