if dTb and not eTb then
TSb.blocked=fTb
end
if not TSb.blocked and(not QSb or TSb.score>QSb.score)then
QSb=TSb
end
if not RSb or TSb.score>RSb.score then
RSb=TSb
end
end
QSb=QSb or RSb
ib._pick={sig=PSb,x=QSb,rooms=LSb}
return QSb
end
