elseif ib.item(ITb)then
KTb=ITb
LTb=tonumber(JTb)
end
if type(KTb)==Avd[570]and ib.item(KTb)then
table.insert(HTb,{key=ITb,id=KTb,cost=LTb or tonumber(ib.item(KTb).cost)or 0,bought=type(JTb)==Avd[1659]and(JTb.bought or JTb.sold or JTb.purchased)or nil})
