ib.LUCK_RESERVE=500
ib.MIN_WORTH=0.02
ib.TOP_WORTH=0.08
function ib.shop(aUb,bUb)
local cUb=ib.cleared(aUb)
local dUb=ib.res(aUb)
local eUb=1+0.1*(ib.items(aUb)._curse_shop or 0)
local fUb=ib.shopAhead(aUb)and math.ceil(ib.LUCK_RESERVE*eUb)or 0
local gUb={}
local hUb,iUb={},0
for jUb,kUb in ipairs(ib.offers(bUb and bUb.data))do
kUb.cost=math.ceil(kUb.cost*eUb)
table.insert(hUb,tostring(ib.item(kUb.id).name or kUb.id))
if not kUb.bought and not ib.isCurse(kUb.id)then
kUb.luck=tonumber(ib.item(kUb.id).luck_increase)~=nil
kUb.v=ib.itemValue(kUb.id,aUb)
if not kUb.luck and kUb.v/math.max(1,kUb.cost)<ib.MIN_WORTH then
iUb=iUb+1
elseif kUb.v>0 and(kUb.luck or cUb>=10 or kUb.v/math.max(1,kUb.cost)>=ib.TOP_WORTH)then
table.insert(gUb,kUb)
end
end
end
table.sort(gUb,function(lUb,mUb)
if lUb.luck~=mUb.luck then
return lUb.luck
end
return lUb.v/math.max(1,lUb.cost)>mUb.v/math.max(1,mUb.cost)
end)
local nUb,oUb,pUb={},0,0
for qUb,rUb in ipairs(gUb)do
if rUb.cost<=dUb-(rUb.luck and 0 or fUb)then
if ib.buy(rUb)then
dUb=ib.res(ib.data())
table.insert(nUb,string.format(Avd[3280],tostring(ib.item(rUb.id).name or rUb.id),rUb.cost))
end
elseif rUb.cost<=dUb then
pUb=pUb+1
else
oUb=oUb+1
end
end
ib.note(string.format(Avd[3281],cUb,#hUb>0 and table.concat(hUb,Avd[1769])or Avd[3282],#nUb>0 and(Avd[3283]..table.concat(nUb,Avd[1769]))or(cUb<10 and Avd[3284]or(pUb>0 and Avd[3285]or Avd[3286])),dUb,oUb>0 and string.format(Avd[3287],oUb)or Avd[584],pUb>0 and string.format(Avd[3288],pUb,fUb)or Avd[584],iUb>0 and string.format(Avd[3289],iUb)or Avd[584]))
F.request(Avd[3290],Avd[3291])
end
function ib.shrine(sUb,tUb)
