function ib.wallet()
local FUb=N.session()and N.session().profile_data or{}
local GUb=FUb.inventory or{}
local HUb={gems=tonumber(N.cur(Avd[1721]))or 0,gold=tonumber(N.cur(Avd[1723]))or 0,items={},units={},unique=0}
