function ib.walletDiff(NUb,OUb)
local PUb={}
if OUb.gems~=NUb.gems then
table.insert(PUb,string.format(Avd[3298],OUb.gems-NUb.gems))
end
if OUb.gold~=NUb.gold then
table.insert(PUb,string.format(Avd[3299],OUb.gold-NUb.gold))
end
for QUb,RUb in pairs(OUb.items)do
if RUb~=(NUb.items[QUb]or 0)then
table.insert(PUb,string.format(Avd[3300],RUb-(NUb.items[QUb]or 0),tostring(QUb)))
end
end
for SUb,TUb in pairs(OUb.units)do
if not NUb.units[SUb]then
table.insert(PUb,Avd[3301]..V.name(TUb))
end
end
if OUb.unique~=NUb.unique then
table.insert(PUb,string.format(Avd[3302],OUb.unique-NUb.unique))
