function ib.openChests(UUb,VUb)
local WUb,XUb,YUb=ib.res(UUb)
local ZUb=ib.lives(UUb)
local _Ub=ib.cleared(UUb)
if not(VUb or _Ub>=ib.ROOMS or ZUb<=1)then
ib.note(string.format(Avd[3304],_Ub,XUb,YUb,ib.luck(UUb)))
F.request(Avd[3290],Avd[3291])
return
end
local aVb,bVb,cVb=0,0,0
local dVb=tonumber(N.cur(Avd[1721]))or 0
local eVb=ib.wallet()
for fVb=1,XUb+YUb+4 do
local gVb,hVb,iVb=ib.res(ib.data())
if hVb+iVb<=0 or cVb>=2 then
break
end
local jVb,kVb
if hVb>0 then
jVb,kVb=F.request(Avd[3305],Avd[3306])
else
jVb,kVb=F.request(Avd[3305],Avd[3306],true)
end
if jVb and kVb~=nil then
F.log(1,Avd[3274],Avd[3307]..(type(kVb)==Avd[1659]and U.json(U.plain(kVb)):sub(1,300)or tostring(kVb)))
end
local lVb=U.now()
while U.now()-lVb<4 do
local mVb,nVb,oVb=ib.res(ib.data())
if nVb<hVb or oVb<iVb then
break
end
task.wait(0.25)
end
local pVb,qVb,rVb=ib.res(ib.data())
if qVb<hVb then
aVb=aVb+(hVb-qVb)
cVb=0
elseif rVb<iVb then
bVb=bVb+(iVb-rVb)
cVb=0
else
cVb=cVb+1
end
task.wait(1)
if qVb<hVb or rVb<iVb then
local sVb=ib.wallet()
local tVb=ib.walletDiff(eVb,sVb)
F.log(1,Avd[3274],(rVb<iVb and Avd[3308]or Avd[3307])..tVb)
P.dg.pay=P.dg.pay or{}
local uVb={}
for vVb,wVb in pairs(sVb.items)do
if wVb~=(eVb.items[vVb]or 0)then
uVb[vVb]=wVb-(eVb.items[vVb]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=rVb<iVb,gems=sVb.gems-eVb.gems,luck=ib.luck(UUb),paid=tVb,items=uVb})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
eVb=sVb
end
end
ib.note(string.format(Avd[3309],aVb,bVb,VUb and Avd[3310]or(ZUb<=1 and Avd[3311]or Avd[3312]),ib.luck(UUb),(tonumber(N.cur(Avd[1721]))or 0)-dVb))
local xVb,yVb,zVb=ib.res(ib.data())
if(VUb or _Ub>=ib.ROOMS)and yVb+zVb>0 then
ib.note(string.format(Avd[3313],yVb,zVb))
W.rec(Avd[2095]).restUntil=os.time()+1800
return Avd[3314]
end
if not VUb then
F.request(Avd[3290],Avd[3291])
end
end
function ib.act(AVb)
