function bb.buildPath()
bb.samples={}
local WYb=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not WYb then
return
end
for XYb,YYb in pairs(WYb)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[XYb.Name])then
local ZYb={}
for _Yb,aZb in ipairs(YYb.points or{})do
table.insert(ZYb,aZb.part.Position)
end
local bZb=0
for cZb=2,#ZYb do
bZb=bZb+(ZYb[cZb]-ZYb[cZb-1]).Magnitude
end
local dZb=0
for eZb=2,#ZYb do
local fZb,gZb=ZYb[eZb-1],ZYb[eZb]
local hZb=(gZb-fZb).Magnitude
local iZb=math.max(1,math.floor(hZb/2))
for jZb=0,iZb-1 do
local kZb=fZb:Lerp(gZb,jZb/iZb)
table.insert(bb.samples,{pos=kZb,prog=(dZb+hZb*jZb/iZb)/math.max(1,bZb),lane=XYb.Name})
end
dZb=dZb+hZb
end
if ZYb[#ZYb]then
table.insert(bb.samples,{pos=ZYb[#ZYb],prog=1,lane=XYb.Name})
end
end
end
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local lZb=tonumber(bb.ld and bb.ld._portal_lanes)
local mZb=fb.laneList(bb.samples)
if lZb and lZb>=1 and mZb and#mZb>lZb then
