end
local wZb,xZb={},0
for yZb,zZb in ipairs(workspace._UNITS:GetChildren())do
local AZb=zZb:FindFirstChild(Avd[1720])
if AZb and AZb:FindFirstChild(Avd[3400])and AZb.player.Value==nil and AZb:FindFirstChild(Avd[3401])and zZb:FindFirstChild(Avd[2663])then
local BZb=tostring(AZb.lane.Value)
if not wZb[BZb]then
wZb[BZb]=true
xZb=xZb+1
