local Ufc,Vfc=F.request(Avd[3543],Avd[3544],Ofc.uuid,N.Util.CFramePLV(Rfc,bb.lookAt(Rfc)))
if Ufc and Vfc then
bb.spent=bb.spent+(Ofc.data.cost or 0)
