table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=Ofc.id,x=math.floor(Rfc.X),z=math.floor(Rfc.Z),cover=math.floor((Sfc or 0)+0.5),why=tostring(Pfc):sub(1,90)})
