bb.placeFail=bb.placeFail or{}
bb.placeFail[Ofc.uuid]=(bb.placeFail[Ofc.uuid]or 0)+1
if bb.placeFail[Ofc.uuid]>=2 then
bb.noSpot[Ofc.uuid]=3
F.log(1,Avd[3500],string.format(Avd[3548],V.name(Ofc.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if Ufc and Tfc>=(Ofc.data.cost or 0)and not bb.random then
local Wfc=bb.spotKey(Rfc)
bb.refused[Wfc]=true
local Xfc=bb.mapKey()
P.blocked[Xfc]=P.blocked[Xfc]or{}
if not bb.refusedRun[Wfc]then
P.blocked[Xfc][Wfc]=(tonumber(P.blocked[Xfc][Wfc])or 0)+1
bb.refusedRun[Wfc]=true
end
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[Ofc.uuid]=(bb.unitRefusals[Ofc.uuid]or 0)+1
if bb.unitRefusals[Ofc.uuid]>=3 then
local Yfc=math.max(1,bb.count(Ofc.uuid))
if P.caps[Ofc.uuid]~=Yfc then
P.caps[Ofc.uuid]=Yfc
F.log(1,Avd[3500],string.format(Avd[3549],V.name(Ofc.id),Yfc))
end
end
