local ric,sic={},0
local function tic(uic,vic)
ric[uic]=(ric[uic]or 0)+vic
sic=sic+vic
end
for wic,xic in pairs(bb.ownDealt)do
if not V.isFarm(xic.id)then
tic(xic.id,xic.v)
end
end
local yic=0
for zic,Aic in pairs(bb.helperDealt)do
tic(Aic.owner or Avd[2112],Aic.v)
yic=yic+1
end
if sic<=0 then
return nil
end
for Bic,Cic in pairs(ric)do
ric[Bic]=Cic/sic
end
return ric,sic,yic
end
function bb.summonSplit()
