P.maps[mjc]=P.maps[mjc]or{}
local ojc=P.maps[mjc]
ojc.walkN=(tonumber(ojc.walkN)or 0)+1
ojc.walk=njc and(njc+(ljc-njc)*math.max(0.2,1/(ojc.walkN+1)))or ljc
fb._walk[mjc]=ojc.walk
end
end
if(djc.potSum or 0)>0 and(djc.dealtSum or 0)>0 then
ijc(Avd[3567],U.clamp(djc.dealtSum/djc.potSum,0.1,2))
