P.maps[pjc]=P.maps[pjc]or{}
local tjc=type(P.maps[pjc].dens)==Avd[1659]and P.maps[pjc].dens or{}
local ujc=(tonumber(P.maps[pjc].densN)or 0)+1
for vjc=1,fb.BINS do
local wjc=(djc.dens[vjc]or 0)/qjc
local xjc=tonumber(tjc[vjc])
tjc[vjc]=xjc and(xjc+(wjc-xjc)*math.max(0.2,1/ujc))or wjc
end
P.maps[pjc].dens,P.maps[pjc].densN=tjc,ujc
