if#djc.pay>=2 then
ijc(Avd[3568],U.clamp(gjc(djc.pay),0.5,2))
end
if not bb.joinedMid then
ijc(Avd[3569],gjc(djc.waveSec))
ijc(Avd[3570],gjc(djc.baseRel))
ejc.baseDps=nil
ijc(Avd[3571],gjc(djc.skip))
local yjc={}
