if Hjc>0 and fb.PRIOR.voteBase+fb.PRIOR.votePer*Hjc>=Cjc+3 then
table.insert(Djc,Gjc.t)
elseif Hjc>0 and Gjc.t<Cjc-2 then
table.insert(Ejc,(Gjc.t-fb.PRIOR.voteBase)/Hjc)
end
