ijc(Avd[3573],gjc(Djc))
ijc(Avd[3574],Ejc[1]and U.clamp(gjc(Ejc),0.2,6)or nil)
ejc.voteWave=type(ejc.voteWave)==Avd[1659]and ejc.voteWave or{}
for Ijc,Jjc in ipairs(djc.votes)do
