local kpc=Qoc.ally and apc>0 and bb.buffLevel(Qoc.ally.types)or 0
local lpc=apc>0 and Qoc.ally and O.community and kpc>0 and((jpc==nil and bpc-Joc>5)or(jpc and jpc.stacks and kpc<(jpc.cap or 1)-0.02))
