function bb.huntChoose(vqc,wqc)
bb.fhP=bb.fhP or 1
local xqc=kb.floor()
local yqc=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local zqc=kb.weatherStrength(kb.weatherNow())
local Aqc=table.find(kb.CARD_PICKS,O.huntCards)and O.huntCards or Avd[1940]
local Bqc,Cqc,Dqc,Eqc
local Fqc={}
for Gqc,Hqc in pairs(vqc)do
local Iqc,Jqc=1,{}
for Kqc,Lqc in pairs(type(Hqc)==Avd[1659]and Hqc.effects or{})do
if type(Lqc)==Avd[1659]then
local Mqc=bb.rogueEffect(Lqc)
Iqc=Iqc*Mqc
table.insert(Jqc,bb.effectText(Lqc))
end
end
if type(Hqc)==Avd[1659]and Hqc.weather then
Iqc=Iqc*kb.weatherStrength(Hqc.weather)/math.max(0.05,zqc)
end
local Nqc=type(Hqc)==Avd[1659]and kb.cardGems(Hqc,wqc)or 0
local Oqc=Iqc>=1 or(bb.fhP*Iqc>=xqc and not yqc)
local Pqc=math.log(math.max(0.05,Iqc))
local Qqc=Pqc*kb.STRENGTH_GEMS+(Oqc and Nqc or-1000)
local Rqc=kb.cardLuck(Hqc)
if Aqc==Avd[585]and Oqc and Rqc>0 then
Qqc=2e6+Rqc*1e4+Nqc
elseif Aqc==Avd[1671]and Oqc then
Qqc=1e6+kb.cardPearls(Hqc,wqc)*10+Nqc+Pqc
elseif Aqc==Avd[1944]then
Qqc=Pqc*1e6+Nqc
end
if not Cqc or Qqc>Cqc then
Bqc,Cqc,Dqc,Eqc=Gqc,Qqc,Iqc,Nqc
end
table.insert(Fqc,string.format(Avd[3656],tostring(Gqc),tostring(type(Hqc)==Avd[1659]and Hqc.title or Avd[1931]),(type(Hqc)==Avd[1659]and Hqc.weather)and(Avd[2069]..tostring(Hqc.weather)..Avd[2043])or Avd[584],tostring(type(Hqc)==Avd[1659]and Hqc.option_type or Avd[1931]),Iqc,math.floor(Nqc+0.5),table.concat(Jqc,Avd[2014])))
end
