bb.fhP=bb.fhP or 1
local yrc=tonumber(P.fh.pmin)or 1
local zrc=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local Arc,Brc,Crc
for Drc,Erc in pairs(wrc)do
local Frc,Grc=1,0
