function bb.learn()
local ssc=bb.calRun and bb.calRun.potBy
if type(ssc)~=Avd[1659]then
return
end
pcall(bb.sampleHelpers,true)
local tsc={}
for usc,vsc in pairs(bb.ownDealt or{})do
if not V.isFarm(vsc.id)then
tsc[vsc.id]=(tsc[vsc.id]or 0)+(tonumber(vsc.v)or 0)
end
end
for wsc,xsc in pairs(bb.helperDealt or{})do
if xsc.owner and V.SUMMONER[xsc.owner]then
tsc[xsc.owner]=(tsc[xsc.owner]or 0)+(tonumber(xsc.v)or 0)
end
end
local ysc,zsc=0,0
for Asc,Bsc in pairs(ssc)do
if Bsc>0 then
ysc=ysc+(tsc[Asc]or 0)
zsc=zsc+Bsc
end
end
if ysc<=0 or zsc<=0 then
return
end
local Csc=ysc/zsc
bb.lastEff={}
for Dsc,Esc in pairs(ssc)do
if Esc>0 and Esc/zsc>0.02 then
local Fsc=P.learn[Dsc]or{eff=1,n=0,v=3}
if(tonumber(Fsc.v)or 0)<3 then
Fsc.eff,Fsc.v=(tonumber(Fsc.eff)or 1)*V.effRescale(Dsc),3
end
local Gsc=math.max(0.02,0.25*math.sqrt(30/(30+Fsc.n)))
local Hsc=U.clamp(((tsc[Dsc]or 0)/Esc)/Csc,0.2,6)
bb.lastEff[Dsc]=math.floor(Hsc*1000+0.5)/1000
Fsc.eff=Fsc.eff+(Hsc-Fsc.eff)*Gsc
Fsc.n=Fsc.n+1
P.learn[Dsc]=Fsc
end
end
local Isc=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Isc and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==Avd[1659]and P.mapLearn or{}
local Jsc=type(P.mapLearn[Isc])==Avd[1659]and P.mapLearn[Isc]or{}
for Ksc,Lsc in pairs(bb.lastEff)do
local Msc=type(Jsc[Ksc])==Avd[1659]and Jsc[Ksc]or{eff=Lsc,n=0}
local Nsc=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Msc.n)or 0))))
Msc.eff=(tonumber(Msc.n)or 0)==0 and Lsc or((tonumber(Msc.eff)or Lsc)+(Lsc-(tonumber(Msc.eff)or Lsc))*Nsc)
Msc.n=(tonumber(Msc.n)or 0)+1
Jsc[Ksc]=Msc
end
Jsc._at=os.time()
P.mapLearn[Isc]=Jsc
if U.count(P.mapLearn)>80 then
local Osc,Psc
for Qsc,Rsc in pairs(P.mapLearn)do
if not Psc or(tonumber(Rsc._at)or 0)<Psc then
Osc,Psc=Qsc,tonumber(Rsc._at)or 0
end
end
P.mapLearn[Osc]=nil
end
end
end
