function bb.baseVerdict(xyc,yyc)
local zyc=(yyc.t or 0)-(xyc.t or 0)
if zyc<bb.BASE_WIN-1 then
return false
end
local Ayc=((tonumber(xyc.base)or 0)-(tonumber(yyc.base)or 0))/zyc
if Ayc<=0 or(tonumber(yyc.base)or 0)<=0 then
return false
end
local Byc=yyc.base/Ayc
local Cyc,Dyc=0,0
local Eyc,Fyc=xyc.foes or{},yyc.foes or{}
for Gyc,Hyc in pairs(Fyc)do
if Hyc.prog>=bb.BASE_END then
Cyc=Cyc+Hyc.hp
local Iyc=Eyc[Gyc]
if Iyc then
Dyc=Dyc+math.max(0,Iyc.hp-Hyc.hp)
end
end
end
for Jyc,Kyc in pairs(Eyc)do
if Kyc.prog>=bb.BASE_END and not Fyc[Jyc]then
Dyc=Dyc+Kyc.hp
end
end
if Cyc<=0 then
return false
end
local Lyc=Dyc/zyc
local Myc=Lyc>0 and Cyc/Lyc or math.huge
local Nyc={baseTime=Byc,loss=Ayc,atEnd=Cyc,rate=Lyc,killTime=Myc}
return Byc<bb.BASE_SOON and Myc>Byc*bb.BASE_MARGIN,Nyc
end
