for tMc,uMc in ipairs(oMc.waves or{})do
if tMc%rMc==0 or tMc== #oMc.waves then
table.insert(sMc,uMc)
end
end
oMc.waves=sMc
pMc=U.json(oMc)
if#pMc<=3900 then
return pMc
end
end
for vMc,wMc in ipairs(oMc.placed or{})do
wMc.why=nil
end
pMc=U.json(oMc)
if#pMc<=3900 then
