local ddd,edd,fdd,gdd,hdd=0,{},{},{},{}
local function idd(jdd,kdd)
jdd=tostring(jdd or Avd[1931])
if not edd[jdd]then
table.insert(fdd,jdd)
end
edd[jdd]=(edd[jdd]or 0)+(tonumber(kdd)or 0)
end
for ldd,mdd in ipairs(bdd)do
if(tonumber(mdd.at)or 0)>=cdd then
ddd=ddd+(tonumber(mdd.n)or 10)
idd(mdd.cur,mdd.cost)
for ndd,odd in pairs(mdd.got or{})do
gdd[ndd]=(gdd[ndd]or 0)+(tonumber(odd)or 0)
end
for pdd,qdd in ipairs(mdd.best or{})do
table.insert(hdd,qdd)
end
end
end
if#bdd==0 then
for rdd,sdd in ipairs(P.spend or{})do
if(tonumber(sdd.at)or 0)>=cdd and tostring(sdd.what):find(Avd[1742])then
ddd=ddd+10
idd(sdd.cur,sdd.cost)
end
end
end
local tdd
if ddd==0 then
tdd= #bdd==0 and Avd[4812]or Avd[4813]
else
local udd={}
for vdd,wdd in ipairs(fdd)do
table.insert(udd,_cd.comma(edd[wdd])..Avd[1830]..wdd)
end
tdd=string.format(Avd[4814],_cd.comma(ddd),mb.andList(udd))
local xdd=mb.sumGot(gdd,hdd)
if xdd~=Avd[584]then
tdd=tdd..Avd[4815]..xdd..Avd[1963]
end
end
local ydd={}
for zdd=1,math.min(20,#bdd)do
local Add=bdd[zdd]
local Bdd=mb.sumGot(Add.got,Add.best)
table.insert(ydd,string.format(Avd[4816],os.date(Avd[1759],tonumber(Add.at)or os.time()),ab.BANNER_NAME[Add.banner]or tostring(Add.banner),tostring(Add.rule or Avd[1743]),_cd.comma(tonumber(Add.cost)or 0),tostring(Add.cur or Avd[584]),Bdd~=Avd[584]and(Avd[2003]..Bdd)or Avd[584]))
end
return tdd,#ydd>0 and table.concat(ydd,Avd[1669])or Avd[4700]
end
